-- Rifts World Book 23: Xiticix Invasion - its bestiary and its notable NPCs.
-- 11 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-xiticix-invasion-creatures.sql
--
-- Written by scripts/bestiary-sql.mjs from 4 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.




-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 11 creatures are in' AS assertion, count(*) AS got, 11 AS want
  FROM creatures WHERE slug IN ('xiticix-nit', 'xiticix-grub', 'xiticix-worker', 'xiticix-digger', 'xiticix-hunter', 'xiticix-leaper', 'xiticix-nanny', 'xiticix-young-queen', 'xiticix-elder-queen', 'xiticix-warrior', 'xiticix-super-warrior');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('xiticix-nit', 'xiticix-grub', 'xiticix-worker', 'xiticix-digger', 'xiticix-hunter', 'xiticix-leaper', 'xiticix-nanny', 'xiticix-young-queen', 'xiticix-elder-queen', 'xiticix-warrior', 'xiticix-super-warrior');
SELECT 'the creatures carry 67 attacks' AS assertion, count(*) AS got, 67 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('xiticix-nit', 'xiticix-grub', 'xiticix-worker', 'xiticix-digger', 'xiticix-hunter', 'xiticix-leaper', 'xiticix-nanny', 'xiticix-young-queen', 'xiticix-elder-queen', 'xiticix-warrior', 'xiticix-super-warrior');

