INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('xiticix-nit', 'Xiticix Nit (Larva)', 'insectoid', 'rifts', 0, 'Survival-minded creature, considered Miscreant.', '{"IQ":"3","ME":"3","MA":"3","PS":"3","PP":"3","PE":"3","PB":"3","Spd":"6"}', '4D6', '5D6', NULL, '2D10', NULL, 'Not an M.D.C. creature: the book prints M.D.C. as None. Attributes are not really applicable; the book says mental stats are animal or lower and physical ones undefined, all effectively 3, with Speed 6. Hit Points 4D6 and S.D.C. 5D6 are the printed figures.', 7, 6, '{"attacks":1}', 'None.', 'R.C.C. Skills/Instincts: None. Combat Skills: None.', 'None printed for the nit stage. It is a legless, worm-like white baby that stays in the Nursery Chamber, flees when it can, and bites weakly only when cornered.', 'None.', 'None printed. No I.S.P. given.', 'Approximately 3 feet (0.9 m) long', '50 lbs (22.5 kg)', 'One year before maturing into a grub', 'Nursery Chamber of a Xiticix hive; never leaves it', 'Cared for by Nannies and Workers', NULL, 'Not a player character. Infant stage of the Xiticix, hatched about three months after the egg is laid. Spends roughly 90% of its time eating, sleeping and growing and stays in this stage 12-14 months, or less when fed Sludge. Nits are packed by the hundreds or thousands in a Nursery. Carries nothing. Not counted in the colony population percentages.', 'A helpless, pale, three-foot grub-like baby with no limbs, five small dark eye spots and a mouth that is only a slit. It is slow, hungry and timid, and only snaps with a toothless mouth when trapped and frightened. A dozen or more squirming together look more disturbing than one alone. Horror Factor is 8 for a cluster of a dozen or more.', 'Rifts World Book 23: Xiticix Invasion p.43-44'),
('xiticix-grub', 'Xiticix Grub (Larva)', 'insectoid', 'rifts', 0, 'Considered Anarchist or Miscreant.', '{"IQ":"1D6+2","ME":"1D6+1","MA":"1D6","PS":"1D6+6","PP":"1D6+2","PE":"3D6","PB":"1D6","Spd":"3D6"}', NULL, NULL, '6D6', '3D6+10', NULL, 'M.D.C. 6D6 on Rifts Earth. For non-M.D.C. worlds the book gives 4D6 Hit Points and 1D4x10 S.D.C. (A.R. 10 printed with that line; no separate A.R. is printed for the M.D.C. version). Spd is running speed; grubs have no wings and cannot fly. I.Q. is in the supernatural-predator category (instinct over intellect). Horror Factor 9 for one, 11 for a group of a dozen or more. Weight up to 200 lbs (91 kg) through year two, passing 300 lbs (136 kg) in year three. Heals 1D4 M.D.C. per 24 hours. Hard Eyes are one third the adult range and M.D.C.', 10, 9, '{"attacks":2,"dodge":1}', '+1 to dodge. Fights only in self defense or when ordered by a Nanny, Warrior or Queen; swarms in bunches and rarely breaks off.', 'R.C.C. Skills/Instincts: basic non-combat abilities of whatever adult type it is growing into (Warrior larvae get Warrior skills, Nanny larvae Nanny skills, and so on), at base skill level without the bonuses the adult lists in parentheses.', 'Has a weak version of the adult hardened eyes (one third the range and M.D.C., and none of the adult optics bonuses). Can hear and speak by ultrasonic sound but has no other antennae abilities yet. Heals 1D4 M.D.C. per day. It has no wings and cannot fly. Until about a month before it spins its cocoon it can still become any adult type, steered by chemicals from the Elder Queen.', 'None.', 'None printed. No I.S.P. given.', '5-6 feet (1.5 to 1.8 m)', 'Up to 200 lbs (91 kg) through year two; passing 300 lbs (136 kg) in year three', 'About one year as a grub (roughly eight months before adult shape begins to show), then a cocoon stage of thirty days, then another year as a young adult before full maturity', 'Nursery Chambers of a Xiticix hive', 'Nannies, Workers and other Xiticix of the hive', NULL, 'Not a player character. Second larval stage, reached about a year after hatching. Stays in the Nursery with the nits, may act as auxiliary guard of the Egg Chambers, and is kicked or carried back by adults when it wanders. Charges and bites, with no weapons carried. Not counted in the colony population percentages.', 'A pale gray-tan, about human-sized larva with a tough spongy shell over head, shoulders, back and most of its six stumpy legs, small antennae and mandibles. It is aggressive and stubborn, hissing and snapping at the Workers who tend it. It has no wings and fights by charging, biting and slashing.', 'Rifts World Book 23: Xiticix Invasion p.44-45'),
('xiticix-worker', 'Xiticix Worker', 'insectoid', 'rifts', 0, 'Most humanoids consider Workers Anarchist or Miscreant evil, but they are not aggressive and live and die in service of their race.', '{"IQ":"1D6+4","ME":"2D6+12","MA":"1D4","PS":"2D6+24","PP":"2D6+10","PE":"2D6+10","PB":"1D6","Spd":"2D6+12"}', NULL, NULL, '1D4x10+10', '1D6x10', NULL, 'Hit Points and S.D.C. are not stored: an M.D.C. being. For non-M.D.C. worlds the young have P.E.+6 Hit Points and 2D6+10 S.D.C. M.D.C. main body 1D4x10+10 for an adult, plus 1D6 per level of experience. Other locations (adult): large eyes (2) 15 each, small eyes (5) 10 each, antennae (2) 15 each, humanoid arms (2) 45 each, claw arms (2) 90 each, legs (2) 65 each, wings (2) 60 each. No resin augmentation. Young: 4D6+6 main body, other parts about half the adult figures. Non-M.D.C. worlds: young Hit Points are P.E. +6 and S.D.C. 2D6+10; both double for full grown adults, with +1D6 Hit Points per level; antennae 20 S.D.C. each, arms and wings 50 each, claw arms 100, legs 70. A.R. is 9 for young and 12 for a mature adult. Spd 2D6+12 is running; flying speed is 1D6x10+60 (average 90, about 60 mph/96 km). All physical attributes are supernatural. Horror Factor 8, or 12 for a squad of 10 or more. Weight 400 lbs (180 kg).', 12, 8, '{"attacks":4,"parry":1,"dodge":1,"roll":4,"pull":2}', 'Bonuses are in addition to attribute and natural ability bonuses: +1 to parry, +1 to dodge, +2 to pull punch, +4 to roll with impact, can perform a kick attack, +3 to save vs Horror Factor, and an additional +2 to save vs poison and disease. Special Combat Moves: None. Punch damages are for a typical Worker and rise for very strong ones (P.S. 31 or higher; see the Rifts Conversion Book).', 'R.C.C. Skills (equivalent to instincts): Wilderness Survival (+10%), Land Navigation (+20%), Navigation: Air (+10%), Basic Math (+10%), Whittling & Sculpting (+15%), W.P. Sword and W.P. Blunt.', 'Has the abilities every Xiticix shares (printed 36-43): seven hardened eyes with 340 degree vision, polarized sight, infrared and ultraviolet sight and 1000 ft (305 m) night vision (+2 initiative, +1 strike, +2 dodge); two prehensile antennae that sense sound, vibration, motion, touch and smell (vulnerable to sonic and vibration attacks, which do an extra die and knock out antenna abilities for 3D4 melee rounds); wings and flight at 1D6x10+60; wall and ceiling adhesion with a carry limit of P.S. x100 lbs; terrible swimming (about 30%); limited regeneration (antennae in 2D6+6 months, hands, arms, feet and wings in 4D6+12 months, eyes, legs and mandibles never); M.D.C. recovery of 1D6 per 24 hours; +6 to save vs poison and disease; chitin exoskeleton (general Horror Factor 10, though this entry prints 8). Worker specifics: great endurance, able to carry twice what P.S. normally allows (P.S. x200 lbs/90 kg); cold, fire and heat attacks, including magical ones, do half damage; its only chemical abilities are the colony identification scent and the chemical alarm. Two of its four arms end in large crab-like pincers with a six-foot (1.8 m) reach.', 'None.', 'None.', '6 feet (1.8 m); the claw arm has a six foot (1.8 m) reach', '400 lbs (180 kg)', NULL, 'Inside and around the Xiticix Hive Network (towers and underground); rarely seen in the field or outside Xiticix territory', 'Other Xiticix of the hive; obeys everything above it in the hierarchy', NULL, 'Not a player character. Average level of experience 3-6th, with 25% only 1-2nd level, 20% reaching levels 7-11 and 5% reaching level 12 or higher. Laborers making up about 30% of a typical colony (a range of 30-40%, trading places with Warriors who run 35-40%): they build, haul, dig, tend the Nannies, young and Queen, and carry messages and supplies, and are drafted as auxiliary fighters in a crisis. Rarely use weapons; only two bladed tools (the Sickle Sword and the Sickle Axe) plus whatever blunt object serves as a club, and rocks to throw (no weapon stats printed in this block). Fights only if attacked, threatened or ordered by a higher Xiticix.', 'A six-foot, brownish-gray laborer that looks much like a Warrior but a bit smaller, with one pair of arms ending in big crab-like pincers. It is quiet, obedient and tireless, and focuses on its task rather than on intruders. When ordered into battle it fights with plain persistence rather than skill.', 'Rifts World Book 23: Xiticix Invasion p.74-76'),
('xiticix-digger', 'Xiticix Digger', 'insectoid', 'rifts', 0, 'Considered Anarchist', '{"IQ":"1D6+5","ME":"2D6+16","MA":"1D6","PS":"3D6+25","PP":"1D6+8","PE":"2D6+12","PB":"1D6","Spd":"3D6+8"}', NULL, NULL, '2D4x10+20+PE', '1D6x10', 'MEx2', 'Adult M.D.C. printed by location. Main body 2D4x10+20 plus the P.E. attribute number, plus an extra 2D6 M.D.C. per level of experience for mature adults. Eyes: large (2) 15 each, small (5) 10 each. Antennae (2) 15 each. Feelers (2) 20 each. Arms (4) 45 each. Legs (2) 80 each. Wings (2) 50 each. Wing coverings (2, on the back) 100 each. The Digger never uses resin augmentation on itself. Young: main body 1D4x10+10, all other parts roughly half the adult figure. Non-M.D.C. worlds: young Hit Points P.E.x3 and S.D.C. 1D6x10+25; double those for full grown adults, then add the P.E. attribute number and 2D6 Hit Points per level of experience. S.D.C. by location: antennae 25 each, feelers 30, arms and wings 50 each, legs 100. P.P.E. 1D6x10. I.S.P. is M.E.x2 plus 1D6 per level of experience. Running Spd is 3D6+8; flying speed is 1D6x10+40 (average speed factor 70, about 48 mph / 77 km), slower than most Xiticix. Supernatural P.S. and other physical attributes. Horror Factor 12 for a group of 10 or more.', 14, 10, '{"attacks":4,"strike":1,"parry":2,"dodge":1,"pull":3,"roll":2}', 'Printed bonuses are in addition to attribute and natural ability bonuses (the common Xiticix optics bonus of +2 initiative, +1 strike, +2 dodge also applies). +3 to save vs possession, +7 to save vs poison and disease (printed as +7 outright; the Hunter and Leaper print an additional +2 on top of the common +6). Young Digger Armor Rating 10, mature adult 14. The special lunging attack must be the first attack of the round. Weapon Notes: rarely uses traditional Xiticix weapons, may grab anything handy including rocks. Strong individuals (P.S. 36 or higher) hit harder than the listed damages.', 'R.C.C. skills (equivalent to instincts): Wilderness Survival (+10%), Land Navigation (+20%), Aerial Navigation (+15%), Basic Math (+40%), Military Fortifications (basic stuff; +20%), General Repair/Maintenance (as it pertains to Xiticix items; +20%), Sculpt/Whittle (+15%), Trap Construction (+10%), Trap/Mine Detection (+20%), W.P. Blunt and one W.P. Ancient skill of choice, excluding Archery. Special skills: Underground Sense of Direction 72% +2%/level (-25% in an unfamiliar subterranean setting); Digging 88% +1%/level; Tunneling 80% +2%/level; Excavation and Architectural Engineering 80% +2%/level; trap making 72% +2%/level.', 'Common Xiticix traits: seven hardened eyes (two large at 15 M.D.C., five small at 10), 340-degree vision, polarized sight (95% direction by the sun, immune to glare and the Blinding Flash spell), infrared and ultraviolet vision, 1000 ft (305 m) nightvision, but blurry close sight so no reading; optics give +2 initiative, +1 strike, +2 dodge; a called shot at an eye is -5 (large) or -9 (small) and only against a stationary target, an antenna called shot is -5. Two prehensile antennae sense motion, wind, temperature and scent: track by sound 66% (1000 ft), motion detection 50% (500 ft), feel vehicles up to 6 miles away and walking humans 2000 ft, hear and speak ultrasonics to 2000 ft, identify known objects by touch 65% (30% if uncommon), temperature 75%, wind 85%, and +1 initiative and +1 dodge against attacks from behind or the side within 12 ft. Sonic or vibration attacks do an extra die of damage and knock out antenna abilities for 3D4 rounds; white noise halves them. Superb smell (odors a mile away, common scents 90% +1%/level, specific scents 54% +2%/level, track by smell alone 75%, hive-mates identified by scent). Chemicals: Chemical Alarm (warns Xiticix within 4 miles), Colony Identification Scent, Trail Scent and resin; no Death Scent, no Call to Arms, no acid spit. Regeneration: M.D.C. 1D6 per 24 hours, antennae regrow in 2D6+6 months, hands, arms, feet and wings in 4D6+12 months, eyes, mandibles and legs never regrow; +6 to save vs poison and disease. Adhesion lets it climb and walk on walls and ceilings at full speed (falls if carrying more than P.S. x100 lbs); poor swimmer 30%; double-jointed, ambidextrous, clawed. Barbed chitin exoskeleton, average Horror Factor 10. Male. Digger specifics: digs through dirt or sand at 20 ft (6.1 m) per melee round without leaving a tunnel, 12 ft through packed earth or clay, 5 ft through rock; tunneling is half that rate and leaves a permanent tunnel (usually 4-5 ft wide by 8-10 ft tall, some 10-15 ft by 12-18 ft); excavates about 20 cubic feet per minute or two, and reinforcing takes ten times longer. M.D.C. material is hard to dig, best rate 10 cubic feet per 1D4+3 minutes by chewing or punching. A Digger can tell whether a tunnel is natural and how old it is. Building: it mixes resin with mud and can produce enough for an 18 ft (5.5 m) wall section or a thin coat over 50 ft (15.2 m) per melee round, though forming the wall takes an hour and it hardens about a quarter hour after that. Weapon and armor making: with Worker help it casts resin melee weapons (blades, spikes, barbs, typically 1D6 or 2D6 M.D.) and resin plating of 20-40% of the wearer natural M.D.C. for fighting-class Xiticix, adding +1 or +2 Horror Factor. M.D.C. bonding resin (Diggers and Queens only): a 6 ft (1.8 m) glob weighing about 100 lbs has about 250 M.D.C. as a pure resin pillar; spread thin it averages about 62 M.D.C. per 10 square feet; mixed with mud the amounts double but the strength halves (125 M.D.C. pillar, about 30-34 M.D.C. per 10 square feet at 1-3 inches thick; outer towers of S.D.C. material coated in the mix have 15-17 M.D.C. per 10 square feet). A retarding enzyme keeps it workable; one Digger can make up to 2000 lbs (900 kg) of pure resin, or 2 tons of mixed resin, every 24 hours. The enzyme (stored in a throat gland) dissolves hardened resin and does 1D6 S.D.C. to skin or fabric; the Coalition makes a synthetic version. Resin Glob Attack: spits a 3 ft (0.9 m) glob (no slow-drying enzyme, so it sets in 1D4+1 melee rounds, 30-75 seconds) once per melee round at a range of 40 ft (12.2 m), counting as one attack; no damage, and it covers about half of a human-sized target, so two globs (legs, then above the waist) restrain a person fully. Legs and feet: -10% speed and -1 initiative for the first two rounds; scraping it off while soft takes 1D4+6 melee actions (6 with turpentine, gasoline or paint thinner); by round three -50% speed, -30% balance, initiative halved, climb and swim halved, no leaping, gymnastics or acrobatics; by round four it is rock hard, speed 0, all combat bonuses reduced to +1, and 100 M.D.C. of damage frees the victim. Torso and arms: first two rounds lose one attack, combat bonuses halved, hand skills -20%; by round three -25% speed, -20% balance, attacks, initiative and bonuses halved, climb and swim -70%, hand and arm skills -50%; by round four speed and balance are halved, bonuses drop to +1, only two attacks per round, no climbing or hand skills, and 100 M.D.C. frees the victim. Head: a Digger will not target the head unless the foe has shown a dangerous head attack (it is not a killer by nature, and needs a Queen, Hunter, Warrior or other leader to suggest it); a Queen will. A covered head means blindness, deafness and muteness, -10 on combat moves, -80% on most physical skills, suffocation in about five minutes (human unconsciousness in two or three), 80 M.D.C. to chisel off, and pounding on it does 1D6 damage direct to Hit Points (1D6+1 M.D.C. to M.D.C. beings) per blow. Rock to Mud, Crumble Rock and Stone to Flesh remove resin. Chemical excretion types: Colony Identification, Chemical Alarm, Resin (with the slow-hardening enzyme) and Trail Scent.', 'None.', 'Considered a Minor Psychic with Ectoplasm and Levitation (both used to make weapons and help in building), Resist Fatigue, Telepathy, Mind Block and Summon Inner Strength. I.S.P.: M.E. x2 plus 1D6 per level of experience.', '8-9 feet (2.4 to 2.7 m) tall in its usual hunched stance, 18 feet (5.5 m) standing mostly erect, 20-22 feet (6 to 6.7 m) long, 4-5 feet (1.2 to 1.5 m) wide at the hips', '1-2 tons', NULL, 'Xiticix hive colonies, in the tunnel network and exterior towers and bridges', 'Other Xiticix; commands a legion of Workers (nearly half of all Workers serve Diggers)', 'Non-Xiticix intruders; rival Xiticix colonies', 'Not a player character. Typical level 4-8, with 20% only 1st-3rd level and 20% reaching levels 9-15. About 10% of a colony. Builder and maintenance caste: digs and shapes the hive, makes the resin weapons and armor plating for fighters, and one Digger attends the Elder Queen. Disposition is task absorbed and mostly non-aggressive; it ignores intruders and releases only a warning chemical unless attacked, and fights only when cornered, when the Call to Arms scent is released, or on the order of a superior (Hunter, Super-Warrior, Nanny or Queen). In a siege it seals and collapses tunnels with resin and rock. Rarely uses weapons even though it makes them. Fights by rearing up and slamming down, then biting a downed foe, or chopping with its shovel-like hands.', 'The Digger is the huge, beetle-like builder of the Xiticix hive: a hunched, blue-black armored giant with four heavy shovel hands, a pair of mandibles and two tactile feelers beside the mouth, and wings hidden under beetle wing cases. It excavates tunnels, raises the concrete-hard resin towers, and makes the resin arms and armor used by the fighting castes. It is a poor fighter by temperament, but its crushing body slam and resin globs can pin or entomb an enemy.', 'Rifts World Book 23: Xiticix Invasion p.45-52'),
('xiticix-hunter', 'Xiticix Hunter', 'insectoid', 'rifts', 0, 'Anarchist (humanoids consider them Diabolic evil; completely loyal and selfless toward the colony)', '{"IQ":"2D6+8","ME":"1D6+21","MA":"1D6","PS":"2D6+18","PP":"2D6+18","PE":"1D6+12","PB":"1D6","Spd":"4D6+12"}', NULL, NULL, '1D4x10+20+PE', '2D4x10+10', 'MEx2', 'Adult M.D.C. printed by location. Main body 1D4x10+20 plus the P.E. attribute number, plus an extra 1D6 M.D.C. per level of experience for mature adults. Eyes: large (2) 15 each, small (5) 10 each. Antennae (2) 15 each. Arms (4) 40 each. Legs (2) 50 each. Wings (2) 50 each. Resin augmentation can raise the main body M.D.C. by 10%-30%. Young: main body 4D6+8, other parts roughly half the adult, no resin augmentation. Non-M.D.C. worlds: young Hit Points P.E.x2 and S.D.C. 3D6+6; double those for full grown adults, then add the P.E. attribute number and 1D6 Hit Points per level of experience. S.D.C. by location: antennae 15 each, arms and wings 35 each, legs 50. P.P.E. 2D4x10+10. I.S.P. is M.E. x2 plus 1D6 per level of experience. Running Spd 4D6+12; flying speed 1D6x10+120 (speed factor 130 to 180, about 90-124 mph / 144-198 km). Supernatural P.S. and physical attributes. Horror Factor 13 for a group of 10 or more.', 13, 10, '{"attacks":5,"initiative":3,"strike":2,"parry":4,"dodge":2,"pull":6,"roll":2,"disarm":2}', 'Bonuses are in addition to attribute and natural ability bonuses (the common optics bonus of +2 initiative, +1 strike, +2 dodge also applies). +2 additional to save vs poison and disease on top of the common +6. Can perform kick attacks. Critical strike on a 19-20. Special bonus: +1 attack per melee round at levels 3, 7, 11 and 15. Special bonus: +1 to save vs Horror Factor at levels 1, 3, 4, 6, 8, 10, 12 and 14. Special combat moves: same as the Warrior (not described on these pages). Young Armor Rating 9, mature adult 13. Hunters also get per-level bonuses to tracking and sensing: sound tracking +1%/level (66% base), motion tracking +2%/level (50% base), track by smell alone +2%/level (75% base), large fire and rain smelling +2%/level (60% base, double range). Weapon Notes: favors the spear, ball and chain, sickle axe and sickle sword, and the Resin Spitter Rifle and TK-Rifle. Strong individuals (P.S. 26 or higher) hit harder than the listed damages.', 'R.C.C. skills (equivalent to instincts): Wilderness Survival (+30%), Land Navigation (+30%), Aerial Navigation (+30%), Basic Math (+30%), Detect Ambush (+20%), Detect Concealment (+15%), Camouflage (+20%), Intelligence (+20%), Prowl (+10%), W.P. Paired Weapons, W.P. Sword, W.P. Spear, W.P. Chain, W.P. Energy Weapon (i.e. Xiticix TK weapons) and two W.P. Ancient of choice, excluding Archery. Enjoys fighting but prefers to track, stalk, spy and plot.', 'Common Xiticix traits: seven hardened eyes (two large at 15 M.D.C., five small at 10), 340-degree vision, polarized sight (95% direction by the sun, immune to glare and the Blinding Flash spell), infrared and ultraviolet vision, 1000 ft (305 m) nightvision, blurry close sight; optics give +2 initiative, +1 strike, +2 dodge; a called shot at an eye is -5 (large) or -9 (small) on a stationary target only, an antenna called shot -5. Two prehensile antennae (double the length of a Warrior pair and only half the thickness) sense motion, wind, temperature and scent; track by sound 66% (1000 ft), motion detection 50% (500 ft), feel vehicles up to 6 miles away and walking humans 2000 ft, ultrasonic hearing and speech to 2000 ft, identify known objects by touch 65%, temperature 75%, wind 85%, +1 initiative and +1 dodge against attacks from behind or the side within 12 ft. Sonic or vibration attacks do an extra die of damage and knock out antenna abilities for 3D4 rounds; white noise halves them. Superb smell, better than other Xiticix: odors a mile away, common scents 90% +1%/level, specific scents 54% +2%/level, track by smell alone 75% +2%/level (Hunters and Super-Warriors), highly skilled at following individual human scent trails. Chemicals: the Colony Identification scent, the Chemical Alarm, the Call to Arms, a Death Scent (released when it dies or falls below 10% M.D.C.), Trail Scent and Spit Acid, plus the Mark Target chemical. Spit Acid: covers 1D4 square feet, 1D4 M.D. per melee round for up to 2D4 rounds (ends after 30-120 seconds, or at once if dosed with salt water), range 80 ft (24.3 m), +2 to strike, up to twice per melee round, each use one attack. Regeneration: M.D.C. 1D6 per 24 hours, antennae regrow in 2D6+6 months, limbs and wings in 4D6+12 months, eyes, mandibles and legs never regrow; +6 to save vs poison and disease. Adhesion lets it climb walls and ceilings at full speed (falls if carrying over P.S. x100 lbs); poor swimmer 30%; double-jointed, ambidextrous, clawed. Barbed chitin exoskeleton, average Horror Factor 10. Male. Flying speed 1D6x10+120. Hunter specifics: the exoskeleton is grass to evergreen green, the head has three long horns, and a second pair of arms on the upper back above the wings ends in curved serrated scythe-like pincers that parry, slash, stab and pin prey. Mark Target chemical: sprayed at up to 40 ft (12.2 m) with no damage; used twice per melee round (each use one attack); the mark lasts 1D4+12 days and is smelled by other Xiticix (two-mile range, 75% detection) and faintly by Dog Boys; marks high-P.P.E. captives (10 or more P.P.E.) for capture and also targets for revenge or assault. Natural Camouflage: color shift takes one melee round, gives +20% to prowl and 98% hide among vegetation when still (-10% off woodland or hive terrain), 75% moving at quarter speed, 55% at half speed, 20% at full speed; -20% in open terrain or alien modern cities; applies in flight against the sky, best 75%. Scouts up to 500 miles (800 km) from the hive.', 'None.', 'Considered a Minor Psychic with Presence Sense (printed Presense Sense), See the Invisible, Sense Evil, Sense Magic, Sense Time and Mind Block. I.S.P.: M.E. x2 plus 1D6 per level of experience.', '7 feet (2.1 m)', '400 lbs (180 kg)', NULL, 'Xiticix hive colonies and the wilderness around and beyond the colony borders', 'Other Xiticix, especially the Leapers and Warriors it commands', 'Non-Xiticix life forms seen as threats; Coalition troops and Psi-Stalkers; rival colonies', 'Not a player character. Typically 4-6th level, with 20% 1st-3rd level and 20% reaching 7th-10th; under 7% live to higher levels. About 6% of a colony. Elite special-operations scout, spy, assassin, strategist and officer (Captain to Colonel ranks) who leads Warriors and Leapers. Usually works alone, in pairs or in small groups of 3-6, and avoids direct combat unless the odds favor it, preferring cunning and ambush. A typical strike squadron is 3-4 Leapers, 1-3 more Hunters and 3-6 Warriors. Typical weapons: spear, ball and chain, sickle axe, sickle sword, Resin Spitter Rifle, TK-Rifle.', 'The Hunter is the green-bodied, spindly scout and commander of the Xiticix. It has a three-horned head, long thin antennae and a second set of scythe-like arms on its back. It stalks quietly, tags high-P.P.E. victims with a lingering scent mark so they can be captured for Sludge, and directs Leapers and Warriors against its prey. It is cool and calculating rather than a berserker, and will withdraw to bring back a larger force.', 'Rifts World Book 23: Xiticix Invasion p.52-55'),
('xiticix-leaper', 'Xiticix Leaper', 'insectoid', 'rifts', 0, 'Anarchist (humanoids consider them Diabolic evil; completely loyal and selfless toward the colony)', '{"IQ":"1D6+6","ME":"1D6+10","MA":"1D6+2","PS":"2D6+16","PP":"2D6+14","PE":"1D6+14","PB":"1D6","Spd":"2D6+30"}', NULL, NULL, '1D4x10+33+PE', '1D4x10+20', 'ME', 'Adult M.D.C. printed by location. Main body 1D4x10+33 plus the P.E. attribute number, plus an extra 1D6 M.D.C. per level of experience for mature adults. Eyes: large (2) 15 each, small (5) 10 each. Antennae (2) 25 each. Arms (4) 50 each. Legs (2) 100 each. Wings (2) 50 each. Resin augmentation can raise the main body M.D.C. by up to 40%. Young: main body 4D6+12, other parts roughly half the adult, no resin augmentation. Non-M.D.C. worlds: young Hit Points P.E.x2 and S.D.C. 3D6+10; double those for full grown adults, then add the P.E. attribute number and 1D6 Hit Points per level of experience. S.D.C. by location: antennae 15 each, arms and wings 35 each, legs 50. P.P.E. 1D4x10+20. I.S.P. is the M.E. attribute number plus 1D6 per level of experience (printed without the x2 that Digger and Hunter have). Running Spd 2D6+30 (about 25 mph / 40 km), or 3D6+70 (about 50-60 mph / 80-96 km) with room to travel in long leaping strides. Flying speed 1D6x10+60 (average speed factor 90, about 60 mph / 96 km). Supernatural P.S. and physical attributes. Horror Factor 15 for a squad of 10 or more.', 12, 11, '{"attacks":4,"initiative":4,"strike":2,"parry":2,"dodge":5,"pull":4,"roll":4,"disarm":2}', 'Bonuses are in addition to attribute and natural ability bonuses (the common optics bonus of +2 initiative, +1 strike, +2 dodge also applies). +2 additional to save vs poison and disease on top of the common +6. Can perform kick attacks (forward kicks are impossible, rear kicks only). Critical strike on an 18-20. Lower dodge bonus when airborne (no figure printed). Special bonus: +1 attack per melee round at levels 2, 5, 9 and 15. Special bonus: +1 to save vs Horror Factor at levels 1, 2, 3, 4, 6, 8, 10, 12 and 14. Does not share the Warrior combat moves; own moves are Rear Power Kick, Leap Kick, parry with foot and leg, and strike with feet while hovering. Strike with feet: when hovering at least 5 ft (1.5 m) off the ground it can strike and parry with its feet for one extra attack per melee round. Young Armor Rating 9, mature adult 12. Weapon Notes: prefers melee weapons: Double-Dagger, Sickle Axe, Beheading Axe and long-sword; also likes the TK-Rifle and Shooting Shoulder Spikes. Strong individuals (P.S. 26 or higher) hit harder than the listed damages. A save vs lethal poison needs 14 or higher.', 'R.C.C. skills (equivalent to instincts): Wilderness Survival (+25%), Land Navigation (+20%), Aerial Navigation (+10%), Basic Math (+20%), Camouflage (+10%), Intelligence (+10%), Surveillance (tailing only at +20%), Prowl (+10%), Escape Artist (+10%), Swim (+15%), W.P. Paired Weapons, W.P. Sword, W.P. Spear, W.P. Energy Weapon (i.e. Xiticix TK weapons) and two W.P. Ancient of choice, excluding archery.', 'Common Xiticix traits: seven hardened eyes (two large at 15 M.D.C., five small at 10; on the Leaper the large eyes sit recessed under an armored brow ridge), 340-degree vision, polarized sight (95% direction by the sun, immune to glare and the Blinding Flash spell), infrared and ultraviolet vision, 1000 ft (305 m) nightvision, blurry close sight; optics give +2 initiative, +1 strike, +2 dodge; a called shot at an eye is -5 (large) or -9 (small) on a stationary target only, an antenna called shot -5. Its antennae are a pair of long spines growing from the shoulder area. They sense motion, wind, temperature and scent; track by sound 66% (1000 ft), motion detection 50% (500 ft), feel vehicles up to 6 miles away and walking humans 2000 ft, ultrasonic hearing and speech to 2000 ft, identify known objects by touch 65%, temperature 75%, wind 85%, +1 initiative and +1 dodge against attacks from behind or the side within 12 ft. Sonic or vibration attacks do an extra die of damage and knock out antenna abilities for 3D4 rounds; white noise halves them. Superb smell (odors a mile away, common scents 90% +1%/level, specific scents 54% +2%/level). Chemicals: Colony Identification, Chemical Alarm and poison only; no Death Scent, Call to Arms, acid spit or Trail Scent. Regeneration: M.D.C. 1D6 per 24 hours (the book also lists enhanced healing for the Leaper without a figure), antennae regrow in 2D6+6 months, limbs and wings 4D6+12 months, eyes, mandibles and legs never regrow; +6 to save vs poison and disease. Adhesion lets it climb walls and ceilings at full speed (falls if carrying over P.S. x100 lbs); unlike other Xiticix it is a comparatively excellent swimmer (Swim +15% R.C.C. skill); double-jointed, ambidextrous, clawed fingers and toes. Barbed chitin exoskeleton, average Horror Factor 10. Male. Wings are smaller, semi-transparent and moth-like, so it flies slower (1D6x10+60) with a lower dodge in the air. Leaper specifics: its two arm pairs end in clawed fingers; the thick hind legs cannot kick forward but kick hard backward. Leaping: 20 ft (6 m) high and 40 ft (12 m) across from a standing start, double with a running start; Power Leap is a running leap of up to 60 ft (19.3 m) high and 120 ft (36 m) across; each leap counts as one melee action; judges height and length to within 2D6 inches. Poisonous Bite: the hooked, spider-like mandibles and pincers inject poison at the same time, which counts as one action, so each poisonous bite uses two melee attacks. It may bite without poison: 5D6 S.D.C. (to toy with human prey) or 3D6 M.D. against Mega-Damage targets or armor. Poison dose: against humans and other mortal S.D.C. beings, 1D4x100 S.D.C./Hit Points and death in about half a melee round (about 7 seconds); a victim who saves (lethal poison, 14 or better) takes only 10% of that (1D4x10, taken from S.D.C. first, then Hit Points) but the victim burns, halving initiative bonus and combat bonuses, -1 attack per round and -30% on skills for 1D4+2 melee rounds; a failed save takes the full damage and the same penalties for 1D6+6 melee rounds. Further bites stack damage and add 1D4 rounds to the duration without worsening penalties. Against Mega-Damage creatures (rival Xiticix, dragons, Faerie Folk, demons, most supernatural beings): 4D6 M.D., plus 1D6 M.D. more at the start of each new melee round for 1D6 rounds, plus the 3D6 M.D. of the bite itself. Poison on weapons: Indian Warriors, Psi-Stalkers, Trapper-Hunters and some D-Bees (not Noli-Bushmen, Greot or Simvan) can extract it and coat arrows, spears and blades; a coated weapon adds 6D6 S.D.C. or 1D4 M.D.; works only on exposed skin; one hit for an arrow or spear, two cutting attacks for a sword or axe.', 'None.', 'Considered a Minor Psychic with See the Invisible, Sense Magic, Impervious to Cold and Impervious to Fire. I.S.P.: M.E. attribute number plus 1D6 per level of experience.', '6 feet (1.8 m) in its normal crouched, bent-leg stance; 10-11 feet (3 to 3.3 m) tall standing fully erect', '400 lbs (180 kg)', NULL, 'Xiticix hive colonies and surrounding territory', 'Other Xiticix; obeys and serves Hunters and Super-Warriors above all', 'Non-Xiticix life forms seen as threats; rival colonies', 'Not a player character. Typically 3-6th level, with 25% 1st-2nd level and about 10% living to levels higher than 7-13; few reach beyond 13th level. About 4% of a colony. Second-class auxiliary combat trooper and assassin: bodyguard and attack dog for Hunters, ambusher, tracker and spy who likes to strike from behind or above and lure foes into traps; the Queens also treat it as a general laborer who can help the Nannies and the work crews. Disposition is anxious, fidgety, aggressive and order-driven. Weapons: prefers melee weapons (Double-Dagger, Sickle Axe, Beheading Axe, long-sword), TK-Rifle and Shooting Shoulder Spikes.', 'The Leaper, also called the Hawk-mouth Xiticix, is the strangest of the Xiticix: a crouching assassin with powerful grasshopper legs, spines along a skull-like head with sunken-looking eyes, and a hooked, spider-like poison bite. It travels in long bounds, kicks backward with great force, and loves ambush, torture and carnage. Hunters use it like a loaded weapon that is pointed at a target and released.', 'Rifts World Book 23: Xiticix Invasion p.55-58'),
('xiticix-nanny', 'Xiticix Nanny', 'insectoid', 'rifts', 0, 'Considered Anarchist by humans, but selfless and wholly devoted to the Hive Colony; will die to protect the baby Xiticix in her care', '{"IQ":"1D6+12","ME":"2D6+12","MA":"1D6+6","PS":"2D6+20","PP":"1D6+10","PE":"2D6+10","PB":"1D6","Spd":"3D6+12"}', NULL, NULL, '1D6x10+80+PE', '2D6x10+30', 'MEx3', 'Hit Points and S.D.C. are not printed for the M.D.C. version; the printed pool is M.D.C. by location. Main body (adult) 1D6x10+80 plus the P.E. attribute number, plus 2D6 M.D.C. per level of experience for mature adults. Locations (adult): large eyes (2) 15 each, small eyes (5) 10 each, antennae (3) 20 each, arms (4) 60 each, legs (2) 70 each, no wings. Never uses resin augmentation. Young: main body 1D4x10+40, all appendages roughly half the adult figures. Non-M.D.C. worlds: Young 1D4x10 Hit Points and 4D6+6 S.D.C.; adults get double, plus the P.E. attribute number, plus 2D6 Hit Points per level; antennae 20 S.D.C. each, arms 45 each, legs 60. A.R. young 12, mature adult 15 (ar field holds the adult figure). I.S.P. printed as M.E. x3 +1D6+1 per level of experience (the formula field holds only the M.E. x3 part; see doubts). P.P.E. printed 2D6x10+30. Spd 3D6+12 is running; she cannot fly. Heals 1D6 M.D.C. per 24 hours (standard Xiticix rate); no Queen-style healing boost is printed for her.', 15, 10, '{"attacks":4,"initiative":1,"strike":1,"parry":1,"dodge":1,"roll":4}', 'Bonuses are in addition to attribute bonuses. +3 to save vs Horror Factor (Horror Factor is 10, or 12 for a group of 10 or more). All of these bonuses are doubled while she is protecting baby Xiticix. Needs a 12 or higher to save vs psionic attack. Critical strike on a natural 20. Special combat moves: none. Standard Xiticix bonuses also apply: optics +2 initiative, +1 strike, +2 dodge; +1 initiative and +1 dodge against an attack from behind or the side within 12 feet; +6 to save vs poison and disease unless stated otherwise. Call to Arms gives non-combat Xiticix extra attacks and bonuses but a Nanny is only mildly affected: one extra attack per round and +2 to M.D. she inflicts. Spit acid is +2 to strike and counts as one attack, twice per round at most. Supernatural P.S. punches do Mega-Damage; the listed damages are for an average Nanny and rise for extraordinarily strong ones (P.S. 26 or higher; the book points to the Rifts Conversion Book).', 'R.C.C. Skills (equivalent to instincts): Wilderness Survival (+10%), Land Navigation (+20%), Basic Math (+30%), Sing (+10%), Camouflage (+15%; used to hide babies and eggs), W.P. Paired Weapons, W.P. Blunt, W.P. Energy Weapon (Xiticix TK weapons).', 'Shares the abilities common to all adult Xiticix (pages 36-43). Seven-eyed insect vision: 340 degree field, polarized sight (95% to find direction from the sun, immune to glare and the Blinding Flash spell), infrared and ultraviolet sight, 1000 foot (305 m) night vision, and an optics bonus. Eyes need a called shot: -5 for a large eye, -9 for a small one, only when the target is still. She has three antennae instead of two (20 M.D.C. each): they track by sound at 66% (1000 ft), sense air motion at 50% (500 ft), feel ground vibration, hear and speak ultrasonic sound out to 2000 feet, identify things by touch (65% common, 30% uncommon), read temperature (75%) and wind (85%), and smell chemicals up to a mile away. A called shot at an antenna is -5; sonic or vibration attacks do an extra die of damage and knock out antenna powers for 3D4 rounds, and white noise halves their range and skill. Antennae regrow in 2D6+6 months, lost arms in 4D6+12 months; eyes, mandibles and legs never regrow. Limited regeneration: 1D6 M.D.C. per 24 hours, +6 to save vs poison and disease, little bleeding. Adhesion: clings to walls and ceilings, can carry up to P.S. x100 lbs without falling, half speed when carrying a heavy load. Poor swimmer (30%), double-jointed, ambidextrous, clawed fingers and toes, barbed chitin exoskeleton. Unlike every other adult Xiticix she has NO wings and cannot fly. Female (only Nannies and Queens are). Chemical abilities: Call to Arms (calls every fighting Xiticix within 1000 feet, brings Warriors in 1D6 rounds), Chemical Alarm (alerts everything within 4 miles, a 6-12 Warrior squad answers), Colony Identification Scent, Trail Scent, and Spit Acid (acid covers 1D4 sq ft, 1D4 M.D. per melee round for up to 2D4 rounds, range 80 feet, goes inert on its own in 30-120 seconds or when doused in salt water). She does not make a Death Scent or resin. MAKES SLUDGE: a regurgitated nutrient paste that cuts the growth of a nit to adult from roughly 37-42 months to 19-22 months. Making it kills a living victim (the doubled P.P.E. at death is the source, not ley lines), takes 2-4 minutes, and costs 25 P.P.E. per pound, with 24 stored in the pound. It keeps one year; any non-Xiticix who eats it takes 1D4x10 direct Hit Points (2D6 M.D. to a Mega-Damage being) plus 2D6 hours of sickness (no initiative, one attack fewer, speed and bonuses halved, skills -30%). Only Nannies and Queens can make it. S.D.C. poison bite: the mandibles deliver 4D6 S.D.C./Hit Points bite damage plus 6D6 S.D.C./Hit Points poison; a successful save vs lethal poison (14+) drops the poison to 1D4 S.D.C. and spares the victim the penalties. Victims who fail halve attacks and bonuses for one melee round (15 seconds). The poison does nothing to Mega-Damage creatures or other Xiticix. Nannies seldom coat weapons with it. Authority: she can order Workers, Diggers and even fighters; only Super-Warriors, young Queens and the Elder Queen outrank her.', 'None.', 'Major Psychic. Powers: Healing Touch, Psychic Surgery, Replenish P.P.E., Suppress Fear, Empathy, Telepathy, See the Invisible, Sense Magic, Sense Time, Mind Block. Saves vs psionic attack on a 12 or higher. I.S.P.: M.E. x3 +1D6+1 per level of experience. Telepathy is used only with other Xiticix (fellow Nannies, assigned Workers, the Queens); empathy and telepathy together read the needs of the babies.', '12 feet (3.6 m)', '900-1,200 lbs (405 to 540 kg)', NULL, 'Egg Chambers, Nurseries and the Queen Chambers deep in the hive; stays close to them even when she leaves', 'The Queens, the Workers assigned to her (they outnumber Nannies in the Nursery three or four to one), and every other Xiticix of the hive', 'Anything that threatens the eggs, nits, grubs or Queens', 'Average level of experience 4-7th, with 20% at 1st-3rd level and 25% at 8th or higher. Not a player character. Colony role: nurse and primary caregiver of eggs, nits and grubs, and maker of Sludge; also marshals Workers into a defensive line and evacuates the young during an attack. The Call to Arms response forms her line from other Nannies 15%, Workers 55%, Warriors 20% and others 10%. Equipment: none printed; most Nannies do not use weapons and fight with mandibles and claws, occasionally grabbing a club-like object. Share of the colony not printed in this block.', 'A hulking, hunchbacked grey insect with yellow markings, long arms, oversized mandibles and a third antenna that makes her head resemble that of a Queen. Glowing oval organs on her abdomen light up as she turns P.P.E. into Sludge. She is slow and careful while tending the young but can move fast, and she is the one Xiticix type that has no wings. She is gentle with the brood and savage toward anyone who threatens it.', 'Rifts World Book 23: Xiticix Invasion p.59-61'),
('xiticix-young-queen', 'Xiticix Young Queen', 'insectoid', 'rifts', 0, 'Humanoids rate the Queens Aberrant or Diabolic evil, but the book says they truly serve the hive selflessly and exist to keep the species going', '{"IQ":"1D6+16","ME":"2D6+16","MA":"1D6+6","PS":"2D6+26","PP":"1D6+16","PE":"1D6+16","PB":"1D6","Spd":"3D6+16"}', NULL, NULL, '1D4x100+PE', '4D6x10', 'MEx3', 'Printed pool is M.D.C. by location. Main body (adult) 1D4x100 plus the P.E. attribute number, plus 4D6 M.D.C. per level of experience. Locations (adult): large eyes (2) 20 each, small eyes (5) 15 each, antennae (3) 25 each, arms (4) 60 each, legs (2) 80 each, wings (2) 80 each. Can add up to 30% to main body M.D.C. with resin but rarely does. Printed line M.D.C. (Young): main body 1D6x10+40, appendages roughly half the adult figures, no resin augmentation. Non-M.D.C. worlds: Young 1D6x10+60 Hit Points and 2D6x10 S.D.C.; full-grown adults get double, plus the P.E. attribute number, plus 4D6 Hit Points per level; antennae 30 S.D.C. each, arms 65 each, legs 90. A.R. young 13, mature adult 16 (ar field holds the adult figure). Spd 3D6+16 is running; flying is 1D6x10+60 (average 90, about 60 mph/96 km), reachable even while carrying the egg sac. I.S.P. M.E. x3 +10 per level of experience (text layer read it as M.E.xS; the rendered page prints M.E.x3). P.P.E. printed 4D6x10. Regenerates 1D4x10 M.D.C. per 24 hours. +1 attack per melee round at levels 4, 9 and 15. Egg sac holds 40-70 eggs (1D4x10+30). Horror Factor 14.', 16, 14, '{"attacks":4,"initiative":1,"strike":1,"parry":2,"dodge":1,"roll":3,"pull":4}', 'Bonuses are in addition to possible attribute and natural ability bonuses. +2 to save vs poison and disease, +5 to save vs Horror Factor, +5 to save vs possession and mind control. Needs a 10 or higher to save vs psionic attack. Critical strike on a 19-20. +1 attack per round at levels 4, 9 and 15. Special combat moves: none (see psionics). Supernatural P.S. punches do Mega-Damage; listed damages are for an average Queen and rise for extraordinarily strong ones (P.S. 31 or higher; the book points to the Rifts Conversion Book). She is never fooled by the scent disguise trick. Also gets the standard Xiticix optics bonus (+2 initiative, +1 strike, +2 dodge).', 'R.C.C. Skills (equivalent to instincts): Wilderness Survival (+25%), Land Navigation (+25%), Aerial Navigation (+20%), Basic Math (+40%), W.P. Paired Weapons, W.P. Energy Weapon (Xiticix TK weapons), and two W.P. Ancient of choice excluding Archery. Leans on cunning, psionics and brute strength.', 'Shares the abilities common to all adult Xiticix (pages 36-43). Seven-eyed insect vision with 340 degree field, polarized sight, infrared and ultraviolet sight and 1000 foot (305 m) night vision; her eyes are tougher than the common figure (20 and 15 M.D.C.). Three antennae (3-5 feet long, 25 M.D.C. each, looking like a crown) track by sound (66%) and motion (50%), feel ground vibration, hear and speak ultrasonic sound out to 2000 feet, read touch, temperature and wind, and smell out to a mile; sonic attacks do an extra die and shut the antenna powers off for 3D4 rounds, white noise halves them. She can fly on a wing pair of 80 M.D.C. each, and keeps her flying speed even with the egg sac. Adhesion lets her cling to walls and ceilings (up to P.S. x100 lbs); swims poorly (30%); double-jointed and ambidextrous; clawed; barbed chitin. Female (Queens and Nannies only). Only the Queens lay eggs; the sac is 12-16 feet long, and she steers the makeup of the colony by chemicals that shape what the eggs and young become. Healing: 1D4x10 M.D.C. per 24 hours; limbs, wings and antennae regrow slowly (wings and arms about 4D6+12 months, antennae 2D6+6 months), eyes, mandibles and legs never do. Chemical abilities: she has all of them - Call to Arms (double the range of a Nanny version and carrying her personal scent), Chemical Alarm (4 mile radius), Colony Identification Scent, Death Scent (released when she dies violently or drops below 10% of M.D.C., smelled 4 miles away), Resin (Queens and Diggers only), Sludge, Spit Acid (1D4 M.D. per round for up to 2D4 rounds, 80 foot range, +2 strike, twice per round), Trail Scent. Sludge: she can make it; doing so costs a living victim, takes 2-4 minutes, 25 P.P.E. per pound yields a pound holding 24 P.P.E., it keeps a year and speeds a nit to adulthood in 19-22 months instead of 37-42; non-Xiticix who eat it take 1D4x10 direct Hit Points (2D6 M.D. to a Mega-Damage being) and 2D6 hours of sickness (no initiative, one attack fewer, speed and bonuses halved, skills -30%). With the Diggers she makes Techno-Wizard style weapons: TK rifle, TK pistol, Spike Shooters and Resin Spitter rifle; how is unknown. Extra +1 attack at levels 4, 9, 15. Command: directs the hive through voice, telepathy and chemicals; all Xiticix serve and defend her.', 'None. (Makes TK weapons by a process the book says might involve psionics and perhaps siphoned magic, unconfirmed.)', 'Major Psychic. Powers: Telepathy, Empathy, Empathic Transmission, Sixth Sense, See the Invisible, Sense Magic, Impervious to Poison, Impervious to Cold and Fire, Levitation, Mind Block, Group Mind Block, Psi-Sword, Psi-Shield, Super Telekinesis. Saves vs psionic attack on a 10 or higher. I.S.P.: M.E. x3 +10 per level of experience.', '20 feet (6.1 m) tall plus 3-5 feet (0.9 to 1.5 m) of antennae; egg sac 12-16 feet (3.6 to 4.9 m) long and 4-6 feet (1.2 to 1.8 m) across', '1-2 tons', NULL, 'Queen Chambers hidden deep in the underground tunnel network of the hive, with birthing rooms and nurseries clustered nearby', 'The Elder Queen (her supreme commander), her elite guard and attendants, and every Xiticix of the hive', 'Anything that threatens her, the hive or the eggs', 'Average level of experience 5-8th, with 15% at 1st-4th and 20% at 9th or higher. Not a player character. Colony role: one of the trusted Generals of the Elder Queen, who lays eggs and shapes the population with chemicals; a hive usually has at least one Elder and two young Queens, and up to a hundred young Queens in a new colony like the six on Rifts Earth. Elite guard that never leaves her: one Super-Warrior, 1D4+2 Hunters, 1D6+6 Warriors and 1D4 Leapers. She is attended by 1D4 Nannies and 1D6+6 Workers. Reinforcements if she is threatened: nearby Nannies and their Workers inside the first melee round; by the second round (30 seconds) 3D6 Warriors, a Super-Warrior and 1D6 Leapers or Hunters; then another 1D4x10 fighters (60% Warriors, or Workers if no fighters are free) about every minute. Equipment: uses whatever weapon is handy; the Xiticix TK weapons are made by Queens.', 'The largest and most imposing Xiticix short of the Elder: a 20-foot dark grey insect with black, green and light grey accents, a crown of three long segmented antennae and a swollen abdomen studded with glowing green organs that holds the egg sac. She is calm, calculating and bold, expects instant obedience, and is as deadly in melee as a Warrior while also wielding a long list of psionic powers. She is buried deep inside the hive behind guards and countless defenders.', 'Rifts World Book 23: Xiticix Invasion p.61-64'),
('xiticix-elder-queen', 'Xiticix Elder Queen', 'insectoid', 'rifts', 0, 'Humanoids rate the Queens Aberrant or Diabolic evil, but the book says they truly serve the hive selflessly and exist to keep the species going', '{"IQ":"1D6+20","ME":"2D6+18","MA":"1D6+10","PS":"2D6+32","PP":"1D6+16","PE":"1D6+16","PB":"1D4","Spd":"3D6+6"}', NULL, NULL, '1D4x100+130', '4D6x10', 'MEx5', 'Printed pool is M.D.C. by location. Main body 1D4x100+130 (no P.E. term is printed) plus 4D6 M.D.C. per level of experience. Locations: large eyes (2) 20 each, small eyes (5) 15 each, antennae (3) 50 each, arms (4) 90 each, legs (2) 110 each, wings (2) 90 each. Can add up to 30% to main body M.D.C. with resin but rarely does. No young-version M.D.C. figure is printed for her. Non-M.D.C. worlds: 5D6x10 +20 per level of experience for Hit Points and 3D6x10+60 S.D.C.; antennae 40 S.D.C. each, arms 75, legs 90, wings 100. A.R. 17. Horror Factor 16. Spd 3D6+6 running; flying is 1D6x10+60, but only if she tears free of her egg sac (not fatal to her: she could live another 6D6 years, but the sac cannot be regrown or reattached); with the sac attached she cannot fly. I.S.P. M.E. x5 +10 per level of experience (rendered page prints M.E.x5). P.P.E. printed 4D6x10, same as the young Queen. Regenerates 1D4x10 M.D.C. per 24 hours. +1 attack per melee round at levels 4, 9 and 15. Egg sac 25-30 feet long, 7-10 feet across, 90-120 eggs (1D4x10+80). Antennae 5-7 feet long, often curved like black horns.', 17, 16, '{"attacks":4,"initiative":3,"strike":2,"parry":4,"roll":2,"pull":4}', 'Bonuses are in addition to possible attribute and natural ability bonuses. +4 to save vs poison and disease, +10 to save vs Horror Factor, +8 to save vs possession and mind control. No dodge bonus is printed. Needs a 10 or higher to save vs psionic attack. Critical strike on a 19-20. +1 attack per round at levels 4, 9 and 15. Special combat moves: none (see psionics). Supernatural P.S. punches do Mega-Damage; listed damages are for an average Elder Queen and rise for extraordinarily strong ones (P.S. 41 or higher; the book points to the Rifts Conversion Book). Never fooled by the scent disguise trick. Also gets the standard Xiticix optics bonus (+2 initiative, +1 strike, +2 dodge).', 'R.C.C. Skills (equivalent to instincts): Wilderness Survival (+25%), Land Navigation (+25%), Aerial Navigation (+20%), Basic Math (+40%), W.P. Paired Weapons, W.P. Energy Weapon (Xiticix TK weapons), and two W.P. Ancient of choice excluding Archery. Leans on cunning, psionics and brute strength.', 'Shares the abilities common to all adult Xiticix (pages 36-43). Seven-eyed insect vision: 340 degree field, polarized sight, infrared and ultraviolet sight, 1000 foot (305 m) night vision. Three antennae of 50 M.D.C. each that track by sound (66%) and motion (50%), feel ground vibration, hear and speak ultrasonic sound to 2000 feet, read touch, temperature and wind, and smell out to a mile; sonic attacks do an extra die and cut off antenna powers for 3D4 rounds, white noise halves them. Her translucent wings (90 M.D.C. each) are no use while the huge egg sac is attached; she can fly only after tearing herself loose, which permanently ends her ability to serve the hive fully (she then asks to be turned into Sludge). Adhesion lets her cling to surfaces (up to P.S. x100 lbs), swims poorly (30%), double-jointed, ambidextrous, clawed, with thicker and spikier black chitin than the young Queens. Female. Healing: 1D4x10 M.D.C. per 24 hours; limbs and antennae regrow slowly, eyes, mandibles and legs never do. Chemical abilities: she has all of them, including Call to Arms (double the range of a Nanny version, her own scent), Chemical Alarm (4 miles), Colony Identification Scent, Death Scent (when she dies violently or falls under 10% M.D.C.; smelled 4 miles), Resin, Sludge and Spit Acid (1D4 M.D. per round for up to 2D4 rounds, 80 feet, +2 strike, twice per round), Trail Scent. Sludge: she can make it; the process kills a living victim, takes 2-4 minutes, costs 25 P.P.E. per pound (24 stored), keeps a year, and cuts the time for a nit to reach adulthood from 37-42 months to 19-22; for non-Xiticix it is poison doing 1D4x10 direct Hit Points (2D6 M.D. to Mega-Damage beings) plus 2D6 hours of sickness (no initiative, one fewer attack, speed and bonuses halved, skills -30%). Helped by Diggers she makes the telekinetic weapons (rifle and pistol), the Resin Spitter and the spike-shooting weapons, by a process nobody has seen. She is the Supreme Commander: every Xiticix, young Queens and Super-Warriors included, obeys her without question; her death means chaos and days of mourning even with an heir ready.', 'None. (Makes TK weapons by a process the book says might involve psionics and perhaps siphoned magic, unconfirmed.)', 'Master Psychic. Powers: Telepathy, Empathy, Empathic Transmission, Sixth Sense, See the Invisible, Sense Magic, Impervious to Poison, Impervious to Cold and Fire, Levitation, Mind Block, Group Mind Block, Psi-Sword, Psi-Shield, Super Telekinesis. Saves vs psionic attack on a 10 or higher. I.S.P.: M.E. x5 +10 per level of experience.', '25-30 feet (7.6 to 9 m) tall plus 5-7 feet (1.5 to 2.1 m) of antennae; egg sac 25-30 feet (7.6 to 9 m) long and 7-10 feet (2.1 to 3 m) across', '3-5 tons', NULL, 'The Elder Queen Chamber deep in the underground tunnels of the hive, with birthing chambers and nurseries clustered beside it', 'The young Queens and Super-Warriors (her nerve center), her elite guard and attendants, and the whole hive', 'Anything that threatens her, the hive or the eggs', 'Average level of experience 9-15th; never lower than 5th. Not a player character. Colony role: the old mother of the hive, whose rule over the colony is total; there is usually one per hive. Elite guards: two Super-Warriors, 1D4+6 Hunters, 1D6+10 Warriors and 1D4+4 Leapers. She is attended by one Digger, 1D4+4 Nannies and 1D6+12 Workers. Equipment: relies on her minions and uses whatever weapon is handy in a pinch.', 'The matriarch of the hive: a black, horned 25-30 foot insect hauling a bloated egg sac as big as herself, with a cape of glittering translucent wings she normally cannot use. Her chitin is darker, thicker and spikier than that of a young Queen, and her antennae often rise like curved ebony horns. She is a Master Psychic, cool and absolutely confident, and the entire hive moves at her command.', 'Rifts World Book 23: Xiticix Invasion p.64-66'),
('xiticix-warrior', 'Xiticix Warrior', 'insectoid', 'rifts', 0, 'Humanoids call them Diabolic evil; in truth they are self-sacrificing soldiers who serve their race and their hive colony', '{"IQ":"1D6+8","ME":"2D6+12","MA":"1D6","PS":"2D6+24","PP":"2D6+12","PE":"1D6+12","PB":"1D6","Spd":"3D6+10"}', NULL, NULL, '1D6x10+20+PE', '1D6x10+10', NULL, 'Horror Factor 10, or 13 for a squad of 10 or more. Main body M.D.C. is 1D6x10+20 plus the P.E. number, and a mature adult adds 2D6 M.D.C. per level of experience (the formula is the base). Per location (adult): large eyes (2) 15 each, small eyes (5) 10 each, antennae (2) 20 each, arms (4) 45 each, legs (2) 65 each, wings (2) 60 each. Resin augmentation can raise main body M.D.C. by up to 40% but is rarely used below 4th level. Young: main body 5D6+10 M.D.C., appendages roughly half the adult figures, no resin. Damage capacity for non-M.D.C. worlds: Young have P.E.x2 Hit Points and 1D4x10+6 S.D.C.; full grown adults have double that plus the P.E. number, and 1D6 Hit Points per level; antennae 20 S.D.C. each, arms and wings 40 each, legs 60 (hp and sdc left null because the adult figure is described only as a doubling). A.R. young 9, mature adult 12. Spd is running; flying speed is 2D4x10+80, average 120 (82 mph/131 km), maximum 160 (105 mph/168 km). P.P.E. printed as 1D6x10+10 (digit-cipher token read from a render).', 12, 10, '{"attacks":5,"initiative":1,"strike":2,"parry":4,"dodge":1,"roll":4,"pull":4,"disarm":2}', 'Bonuses are in addition to attribute and natural ability bonuses. Initiative +1 is gained at levels 1, 3, 6, 9, 12 and 15 (so the +1 shown is the level-one figure); +2 strike, +4 parry, +1 dodge, +2 disarm, +4 pull punch, +4 roll with impact, can kick, additional +4 to save vs poison and disease. Extra attack per melee round at levels 2, 5, 8 and 12; +1 to save vs Horror Factor at levels 1, 2, 3, 4, 5, 6, 8, 9, 11, 13 and 15. Critical strike on a natural 18-20 (double damage). Supernatural P.S.; damages given are for an average Warrior and may rise at P.S. 31 or higher. Special combat moves: (1) attack with two hands and parry with two; four arms plus 340 degree senses allow simultaneous and multiple actions, so it can parry one or two other opponents (front, sides, behind) while fighting, or fight two or three at once while keeping one or two hands free to parry. (2) Grapple/Wrestle and Hit: hold, pin or grapple with two hands and strike with the other two. (3) Two-Handed Paired Weapon Attack: two hands strike the same target together, counts as ONE melee action, the defender rolls one parry (success blocks both, failure means both hit); unlike other fighters the four-armed Xiticix keeps its parry and need not spend an action to parry afterward. (4) Four-Handed attack: all four arms strike one area as ONE melee action, one parry roll blocks all four, a failed parry means all four hit (identical blows: roll one and multiply by four); afterward it cannot parry the next attack without spending a melee action and is wide open to attack from above or behind; used mainly in desperation, frenzy or overconfidence. Normal combat strikes with one hand per attack and can parry attacks from the sides and behind, but not while using the paired or four-handed attack. (5) Simultaneous Attack: strikes at the same instant as the foe, and can try to parry with its other pair of hands but only on a straight unmodified roll that must beat the attacker strike roll; only Hunters, Warriors and Super-Warriors can do this and not if both antennae are lost. S.D.C. POISON (bite or coated weapon): a poisoned bite does 4D6 S.D.C./Hit Points from the nip plus 6D6 S.D.C./Hit Points of poison, and unless the victim saves vs lethal poison the victim is nauseous, vomits and convulses, halving attacks per melee round and combat bonuses for one melee round (15 seconds). A successful save vs lethal poison (14 or higher) means only 1D4 S.D.C. from the poison plus the 4D6 bite, with no penalties. It has no effect on Mega-Damage creatures or other Xiticix. A non-poisonous bite does 2D6 M.D. Poison coated on a weapon lasts one strike with a small weapon (short sword, knife, spearhead, mace, morning star) or two strikes with a large blade (large sword, axe), and the weapon must break the skin. Spit acid: see attacks.', 'R.C.C. Skills (equivalent to instincts): Wilderness Survival +30%, Land Navigation +30%, Navigation: Air +25%, Basic Math +20%, Detect Ambush +10%, Detect Concealment +5%, W.P. Paired Weapons, W.P. Sword, W.P. Spear, W.P. Knife, W.P. Energy Weapon (i.e. Xiticix TK weapons) and three W.P. Ancient of choice, excluding Archery. Printed note: Warriors love to fight, it is their whole mission in life.', 'Shared Xiticix traits (pp.36-43): Seven compound eyes (two big, three small, two at the temples) give a 340 degree view, polarized sight, infrared and ultraviolet vision and 1000 foot (305 m) night vision, and bring +2 initiative, +1 strike and +2 dodge; eyes are hardened and a called shot at one is -5 (large) or -9 (small), only against a stationary target. The antennae work as extra feelers that smell, hear and touch: tracking by sound 66%, motion tracking 50%, ultrasonic hearing and speech out to 2000 feet (610 m), ground vibrations felt from miles off, identifying objects by touch 65%, a +1 initiative and +1 dodge bonus when something fast closes on it from the rear or flank inside 12 feet; losing both antennae removes these senses and makes the creature a frenzied loner, while sonic and white-noise attacks hurt them (sonic damage gets one extra die and shuts the antennae down for 3D4 melee rounds). Smell is extreme: scents out to a mile, common smells 90% +1% per level (300 feet per level), specific odors 54% +2% per level, tracking by scent alone 75%, trails up to six days old. Chemical glands cover the colony identification scent, chemical alarm (4 mile radius, 1D4 melee round response inside the hive) and the death scent released when killed or taken below 10% M.D.C. Limited regeneration: antennae in 2D6+6 months, hands, arms, feet and wings in 4D6+12 months; eyes, mandibles and legs never return. Normally heals 1D6 M.D.C. per 24 hours and is +6 to save vs poison and disease. Sticks to and climbs almost any surface at full running speed (limit P.S. x100 pounds carried), swims only at 30%, is double-jointed, ambidextrous, clawed, winged and covered in barbs, M.D.C. chitin that resin plating can augment. Warrior extras: it gains the per-level hunting and tracking bonuses described for the species and is one of three fighting types expert at following individual scents; it carries chemical glands for colony identification, chemical alarm, death scent and spit acid, plus a poison it can secrete onto its weapons. Flies at 2D4x10+80.', 'None.', 'None.', '7 feet (2.1 m)', '500 lbs (227 kg)', NULL, 'Xiticix hive towers and tunnels; patrols the hive territory, its borders and the skies above the Hive Cities', 'Other Xiticix of its own hive colony; obeys Queens, Nannies, Super-Warriors and Hunters', 'Everything that is not Xiticix or of Xiticix manufacture; treated as an enemy and destroyed', 'Not a player character. Average level of experience is 1-5; only about 33% ever reach levels 6-8 and under 10% survive to levels 9-15. The most numerous Xiticix type, normally 35-40% of a colony (30% when Workers are at 40%), serving as patrol soldiers, border defenders and hive guards, with squads of 6 to 12 sent to investigate any alarm. Typical kit: one Xiticix spear, one sickle-bladed short sword, plus two to four further weapons it picks itself (extras can be duplicates). Ranged weapons by share of Warriors: TK-Rifle about 33%, Resin Spike Gun 20%, Resin Rifle (the Resin Spitter) 5%. Weapons are slung or hooked on spines and resin armor; the only non-Xiticix item it uses is a belt.', 'The Warrior is the soldier caste most often met in the wild: a black, broad-shouldered, four-armed chitinous insect-man about seven feet tall with large mandibles and wings. It lives by instinct, patrols the hive and its borders, and attacks anything foreign without pause or mercy, fighting until it or the enemy is destroyed. It bites with a poison that harms only living, S.D.C. victims, and it favors melee blades and the TK weapons of the colony.', 'Rifts World Book 23: Xiticix Invasion p.66-70'),
('xiticix-super-warrior', 'Xiticix Super-Warrior', 'insectoid', 'rifts', 0, 'Humanoids call them Diabolic evil; in truth they are self-sacrificing soldiers who serve their race and their hive colony', '{"IQ":"1D6+11","ME":"2D6+14","MA":"1D6+2","PS":"2D6+28","PP":"2D6+18","PE":"1D6+18","PB":"1D4","Spd":"3D6+24"}', NULL, NULL, '2D4x10+60+PE', '1D4x10+60', 'MEx2', 'I.S.P. printed as M.E. attribute x2 +1D6+1 per level of experience; the base M.E.x2 is stored. Main body M.D.C. is 2D4x10+60 plus the P.E. number, and a mature adult adds 2D6 M.D.C. per level of experience (the formula is the base). Per location (adult): large eyes (2) 20 each, small eyes (5) 15 each, antennae (2) 25 each, arms (6) 55 each, legs (2) 120 each, wings (2) 75 each. Resin augmentation can raise main body M.D.C. by up to 40% and often does. Young: main body 1D4x10+30 M.D.C., appendages roughly half the adult figures. Damage capacity for non-M.D.C. worlds: Young have P.E.x3 Hit Points and 2D6x10+25 S.D.C.; full grown adults have double that plus the P.E. number, and 2D6 Hit Points per level; antennae 25 S.D.C. each, arms, legs and wings 100 each (hp and sdc left null because the adult figure is described only as a doubling). A.R. young 11, mature adult 16. I.S.P. printed as M.E. attribute x2 +1D6+1 per level of experience. Spd is running; flying speed is 2D4x10+80, average 120 (82 mph/131 km), maximum 160 (105 mph/168 km). Heals 2D6 M.D.C. per 24 hours (1D6 every 12 hours).', 16, 13, '{"attacks":6,"initiative":4,"strike":3,"parry":6,"dodge":2,"roll":2,"pull":6,"disarm":3}', 'Bonuses are in addition to attribute and natural ability bonuses: +4 initiative, +3 strike, +6 parry, +2 dodge, +3 disarm, +6 pull punch, +2 roll with impact, can kick, +6 to save vs possession, +4 to save vs mind control, additional +4 to save vs poison and disease. Extra attack per melee round at levels 2, 4, 8, 12 and 15; +2 to save vs Horror Factor at levels 1, 2, 4, 6, 9, 12 and 15. Horror Factor 13 individually, 16 if three or more Super-Warriors or one leads a squadron of 10 or more Warriors. Critical strike on a natural 18-20 (double damage). Supernatural P.S.; damages given are for a typical Super-Warrior and may rise at P.S. 36 or higher. Needs a 12 or higher to save vs psionic attack. Special combat moves, fundamentally the same as the Warrior but with six arms: (1) Grapple/Wrestle and Hit: hold, pin or grapple with 2-4 hands and strike with the other 2-4. (2) Two-Handed Paired Weapon Attack: two hands strike the same target as ONE melee action, one parry roll blocks or fails both; since it uses two arms to strike and keeps others to parry, the usual loss of the automatic parry does not apply. (3) Four-Handed Paired Weapon Attack (used frequently): four arms strike one area as ONE melee action, one parry roll blocks all four, a failed parry means all four hit (identical blows: roll one and multiply by four); unlike the Warrior it still has a pair of arms free to parry the next attack without using a melee action, and can parry a second opponent attacking from above or behind. (4) Normal combat: one hand per strike, each strike one melee attack, can engage 2-6 opponents striking and parrying as normal. (5) Simultaneous Attack: strikes at the same instant as the foe while trying to parry with its other two pairs of hands (four limbs), at HALF the normal parry bonus; only fighting class Xiticix can do this. Spit acid: +3 to strike (see attacks). Extra Super-Warrior bonuses per level apply to many hunting, tracking and fighting abilities (tracking by sound +1% per level, tracking by scent +2% per level).', 'R.C.C. Skills (equivalent to instincts): Wilderness Survival +40%, Land Navigation +30%, Aerial Navigation +25%, Basic Math +30%, Detect Ambush +20%, Detect Concealment +15%, Intelligence +10%, Prowl +5%, W.P. Paired Weapons, W.P. Sword, W.P. Spear, W.P. Energy Weapon (i.e. Xiticix TK weapons) and three W.P. Ancient of choice, excluding Archery. Printed note: they live to fight.', 'Shared Xiticix traits (pp.36-43): Seven compound eyes (two big, three small, two at the temples) give a 340 degree view, polarized sight, infrared and ultraviolet vision and 1000 foot (305 m) night vision, and bring +2 initiative, +1 strike and +2 dodge; eyes are hardened and a called shot at one is -5 (large) or -9 (small), only against a stationary target. The antennae work as extra feelers that smell, hear and touch: tracking by sound 66%, motion tracking 50%, ultrasonic hearing and speech out to 2000 feet (610 m), ground vibrations felt from miles off, identifying objects by touch 65%, a +1 initiative and +1 dodge bonus when something fast closes on it from the rear or flank inside 12 feet; losing both antennae removes these senses and makes the creature a frenzied loner, while sonic and white-noise attacks hurt them (sonic damage gets one extra die and shuts the antennae down for 3D4 melee rounds). Smell is extreme: scents out to a mile, common smells 90% +1% per level (300 feet per level), specific odors 54% +2% per level, tracking by scent alone 75%, trails up to six days old. Chemical glands cover the colony identification scent, chemical alarm (4 mile radius, 1D4 melee round response inside the hive) and the death scent released when killed or taken below 10% M.D.C. Limited regeneration: antennae in 2D6+6 months, hands, arms, feet and wings in 4D6+12 months; eyes, mandibles and legs never return. Normally heals 1D6 M.D.C. per 24 hours and is +6 to save vs poison and disease. Sticks to and climbs almost any surface at full running speed (limit P.S. x100 pounds carried), swims only at 30%, is double-jointed, ambidextrous, clawed, winged and covered in barbs, M.D.C. chitin that resin plating can augment. Super-Warrior extras: its antennae are hidden and extend when needed; it gets the per-level tracking and fighting bonuses; it has the Call to Arms, Death Scent, Trail Scent and Spit Acid glands plus colony identification and chemical alarm; spit acid reaches 100 feet (30.5 m), +3 to strike, acid does 1D4 M.D. each round, lasting up to 2D4 rounds, over 1D4 square feet; it heals and regrows limbs twice as fast as other Xiticix (M.D.C. at 2D6 per 24 hours, antennae in 1D6+3 months, wings and limbs in 2D6+6 months); it can order any Xiticix except the Queens.', 'None.', 'Considered a Major Psychic with See the Invisible, Deaden Senses, Mind Block and Electrokinesis. Needs a 12 or higher to save vs psionic attack. I.S.P.: M.E. attribute x2 +1D6+1 per level of experience.', '10-12 feet (3 to 3.6 m)', '700-1000 lbs (315 to 450 kg)', 'Rarely lives beyond 13th level', 'Xiticix hive territory; found with company-sized squadrons and larger forces, on important seek and destroy missions, and among the elite guards of a Queen', 'Warriors, Hunters and Leapers follow its orders; serves the young and Elder Queens', 'Any non-Xiticix life form, especially humanoids and other intelligent beings', 'Not a player character. Typical level 3-7; 20% are only 1st-2nd level and 15% reach levels 8-13. Acts as a commander, holding the equivalent of general-officer rank (Brigadier up to Lieutenant General) among the Xiticix, and can order any Xiticix except the Queens; every Queen elite guard includes at least one (the Elder Queen guard lists two). Typical kit: a Xiticix spear, a big sword or axe, one or two sets of paired Double-Daggers, and two or three further weapons it picks itself (extras can be duplicates). Ranged weapons by share of Super-Warriors: TK-Rifle about 25%; Resin Rifle or TK-Pistol 5%, though most prefer natural abilities, psionics and brute strength. Popular as gladiators in arenas, particularly in Atlantis.', 'The Super-Warrior is a huge, six-armed war leader of the hive, ten to twelve feet tall, who loves combat and kills quickly and without mercy. It plans and leads operations, spits acid, uses minor psionics and fights with several arms at once while keeping others free to parry. Warriors, Hunters and Leapers obey it without question, and only the Queens outrank it.', 'Rifts World Book 23: Xiticix Invasion p.70-74');
INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'xiticix-nit', 'Bite', '1D6', 0, 'melee', 'S.D.C. damage; one attack per melee round; toothless bite used only when cornered', 0),
('creature', 'xiticix-grub', 'Bite', '4D6', 0, 'melee', 'S.D.C. damage; two attacks per melee round split between bites and claw slashes', 0),
('creature', 'xiticix-grub', 'Claw slash', '3D6', 0, 'melee', 'S.D.C. damage', 1),
('creature', 'xiticix-worker', 'Restrained Punch', '5D6', 0, 'melee', 'S.D.C. damage', 0),
('creature', 'xiticix-worker', 'Normal Punch or Kick', '3D6', 1, 'melee', NULL, 1),
('creature', 'xiticix-worker', 'Power Punch or Kick', '6D6', 1, 'melee', 'Counts as two attacks', 2),
('creature', 'xiticix-worker', 'Bite', '3D6', 1, 'melee', NULL, 3),
('creature', 'xiticix-worker', 'Pincer/Scissor Claw', '5D6', 1, 'melee', NULL, 4),
('creature', 'xiticix-digger', 'Restrained Punch', '5D6', 0, NULL, 'S.D.C.', 0),
('creature', 'xiticix-digger', 'Normal Punch', '4D6', 1, NULL, NULL, 1),
('creature', 'xiticix-digger', 'Power Punch', '1D4x10', 1, NULL, 'Counts as two attacks', 2),
('creature', 'xiticix-digger', 'Bite Attack', '4D6', 1, NULL, NULL, 3),
('creature', 'xiticix-digger', 'Special Lunging Attack/Body Slam', '1D6x10', 1, NULL, 'Counts as two melee attacks and must be the first attack of the round', 4),
('creature', 'xiticix-digger', 'Resin Glob Attack', 'None', 0, '40 feet (12.2 m)', 'Once per melee round, counts as one attack. A 3 ft (0.9 m) glob covers about half a human-sized target and hardens in 1D4+1 melee rounds. Legs and feet: -10% speed and -1 initiative at first, rock hard by round 4 (speed 0, bonuses reduced to +1); torso and arms: attacks and bonuses halved, then hard by round 4 (two attacks, bonuses +1). Removal needs 100 M.D.C. of damage (80 M.D.C. if the head was covered); 1D4+6 melee actions to scrape off while still soft. No strike bonus is printed for it.', 5),
